    self.assertEqual(relay({"command": "count", "protocol": "2", "receipts": [
        receipt("R-1", "D-1"),
        receipt("R-2", "D-1", "2026-04-01T09:00:00Z"),
        receipt("R-3", "D-2"),
    ]}), {"protocol": "2", "accepted_count": 2, "duplicate_count": 1})

